 186 │ /**
 187 │  * Prefer the feature-flagged shared provider for linked users. Any missing
 188 │  * identity, link, configuration, or exchange failure falls through to the
 189 │  * existing Rivet/Portkey/BYO chain and ultimately the deterministic local
 190 │  * generator.
 191 │  */
 192 │ async function pickProvider(
 193 │   ctx: ActionCtx,
 194 │   feature: string,
 195 │   alias: NotOrganicModelAlias = "balanced",
 196 │ ): Promise<ProviderConfig | null> {
 197 │   if (notOrganicEnabled()) {
 198 │     try {
 199 │       const identity = await ctx.auth.getUserIdentity();
 200 │       if (identity) {
 201 │         const link = await ctx.runQuery(linkedDidReference, {
 202 │           productSubject: identity.subject || identity.tokenIdentifier,
 203 │         });
 204 │         if (link) {
 205 │           const token = await issueNotOrganicAccessToken({
 206 │             did: link.did,
 207 │             feature,
 208 │             capabilities: [`infer:${alias}`],
 209 │             sessionVersion: link.sessionVersion,
 210 │           });
 211 │           const route = notOrganicOpenAiRoute(
 212 │             token,
 213 │             alias,
 214 │             feature,
 215 │             notOrganicIssuer(),
 216 │           );
 217 │           const provider = createOpenAI({
 218 │             baseURL: route.baseURL,
 219 │             apiKey: route.apiKey,
 220 │             headers: route.headers,
 221 │             fetch: route.fetch,
 222 │           });
 223 │           return {
 224 │             model: provider.chat(route.model),
 225 │             // Preserve the public response union: Not Organic is an
 226 │             // OpenAI-compatible transport, distinguished by alias + headers.
 227 │             label: "openai",
 228 │             modelId: alias,
 229 │           };
 230 │         }
 231 │       }
 232 │     } catch (error) {
 233 │       console.warn(
 234 │         `[twyne:notorganic] ${feature} unavailable; using existing provider fallback`,
 235 │         error,
 236 │       );
 237 │     }
 238 │   }
 239 │   return pickLegacyProvider();
 240 │ }
