 251 │ const typeOrder: FeedbackType[] = [
 252 │   "critique",
 253 │   "suggestion",
 254 │   "encouragement",
 255 │   "perspective",
 256 │ ];
 257 │ 
 258 │ function classifyType(text: string, fallback: FeedbackType): FeedbackType {
 259 │   const scores = typeOrder.map((t) => ({
 260 │     t,
 261 │     score: (text.match(typeKeywords[t]) ?? []).length,
 262 │   }));
 263 │   scores.sort((a, b) => b.score - a.score);
 264 │   if (scores[0]?.score > 0) return scores[0].t;
 265 │   return fallback;
 266 │ }
