 286 │   const start = Date.now();
 287 │   const { tools, getAnchor } = buildQuoteTools(req.draftText);
 288 │ 
 289 │   try {
 290 │     const first = await generateText({
 291 │       model: provider.model,
 292 │       system,
 293 │       prompt: user,
 294 │       temperature,
 295 │       maxOutputTokens: maxTokens,
 296 │       tools,
 297 │       stopWhen: stepCountIs(3),
 298 │       experimental_telemetry: {
 299 │         isEnabled: tracingEnabled,
 300 │         functionId: feature,
 301 │         metadata: {
 302 │           feature,
 303 │           persona: req.persona.id,
 304 │           provider: provider.label,
 305 │           model: provider.modelId,
 306 │         },
 307 │       },
 308 │     });
 309 │     let text = first.text;
 310 │     let usage = normalizeAiUsage(first.totalUsage);
 311 │     let visibleText = stripReasoningTags(text);
 312 │     // Any reply that reached for the reasoning channel is discarded and asked
 313 │     // again, not merely stripped: a note with the model's thinking bleeding
 314 │     // through it reads worse than one that cost a second call.
 315 │     if (!visibleText || hasReasoningTags(text)) {
 316 │       const retry = await generateText({
 317 │         model: provider.model,
 318 │         system,
 319 │         prompt: `${user}\n\nRespond with your note as plain visible text. Do not place your whole answer inside <think> tags.`,
 320 │         temperature,
 321 │         maxOutputTokens: maxTokens,
 322 │         tools,
 323 │         stopWhen: stepCountIs(3),
 324 │         experimental_telemetry: {
 325 │           isEnabled: tracingEnabled,
 326 │           functionId: `${feature}:retry`,
 327 │           metadata: {
 328 │             feature,
 329 │             persona: req.persona.id,
 330 │             provider: provider.label,
 331 │             model: provider.modelId,
 332 │           },
 333 │         },
 334 │       });
 335 │       usage = normalizeAiUsage(retry.totalUsage) ?? usage;
 336 │       const retryVisible = stripReasoningTags(retry.text);
 337 │       visibleText =
 338 │         (!hasReasoningTags(retry.text) && retryVisible) ||
 339 │         visibleText ||
 340 │         retryVisible ||
 341 │         removeReasoningTagMarkers(retry.text);
 342 │     }
 343 │     const traceId = await captureServerAiGeneration({
 344 │       feature,
 345 │       provider: provider.label,
 346 │       model: provider.modelId,
 347 │       req,
 348 │       output: visibleText,
 349 │       latencyMs: Date.now() - start,
 350 │       temperature,
 351 │       maxTokens,
 352 │       spanName: feature,
 353 │       usage,
 354 │       observability,
 355 │     });
 356 │ 
 357 │     const cleaned = visibleText.trim();
 358 │     await flushArize();
 359 │     return {
 360 │       text: cleaned || "(no response)",
 361 │       type: classifyType(cleaned, fallbackType),
 362 │       provider: provider.label,
 363 │       traceId,
 364 │       anchor: getAnchor() ?? req.anchor,
 365 │     };
 366 │   } catch (err) {
 367 │     await captureServerAiGeneration({
 368 │       feature,
 369 │       provider: provider.label,
 370 │       model: provider.modelId,
 371 │       req,
 372 │       latencyMs: Date.now() - start,
 373 │       temperature,
 374 │       maxTokens,
 375 │       spanName: feature,
 376 │       observability,
 377 │       error: err,
 378 │     });
 379 │     await flushArize();
 380 │     throw err;
 381 │   }
 382 │ }
