 384 │ /**
 385 │  * Generate plain long-form text from a system + user prompt, with the same
 386 │  * empty-after-strip retry as {@link runLlm}. Used for the room synthesis and
 387 │  * the narrative rubric review, neither of which speaks as a single persona.
 388 │  */
 389 │ async function runPlainLlm(
 390 │   provider: ProviderConfig,
 391 │   system: string,
 392 │   user: string,
 393 │   maxTokens: number,
 394 │   feature: string,
 395 │ ): Promise<string> {
 396 │   const gen = async (prompt: string, suffix?: string) =>
 397 │     generateText({
 398 │       model: provider.model,
 399 │       system,
 400 │       prompt,
 401 │       temperature: 0.4,
 402 │       maxOutputTokens: maxTokens,
 403 │       experimental_telemetry: {
 404 │         isEnabled: tracingEnabled,
 405 │         functionId: suffix ? `${feature}:${suffix}` : feature,
 406 │         metadata: {
 407 │           feature,
 408 │           provider: provider.label,
 409 │           model: provider.modelId,
 410 │         },
 411 │       },
 412 │     });
 413 │   const { text } = await gen(user);
 414 │   let visible = stripReasoningTags(text);
 415 │   if (!visible || hasReasoningTags(text)) {
 416 │     const retry = await gen(
 417 │       `${user}\n\nRespond with plain visible text. Do not place your whole answer inside <think> tags.`,
 418 │       "retry",
 419 │     );
 420 │     const retryVisible = stripReasoningTags(retry.text);
 421 │     visible =
 422 │       (!hasReasoningTags(retry.text) && retryVisible) ||
 423 │       visible ||
 424 │       retryVisible ||
 425 │       removeReasoningTagMarkers(retry.text);
 426 │   }
 427 │   await flushArize();
 428 │   return visible.trim();
 429 │ }
