 572 │ 
 573 │ const INTERVIEW_FIELDS = [
 574 │   "workingTitle",
 575 │   "format",
 576 │   "audience",
 577 │   "goal",
 578 │   "tone",
 579 │   "constraints",
 580 │   "successSignal",
 581 │ ] as const satisfies ReadonlyArray<keyof ProjectInterviewAnswers>;
 582 │ 
 583 │ /**
 584 │  * The interviewer's contract. Three optional tagged segments, all parsed by
 585 │  * the same `extractTaggedJson` helper:
 586 │  *
 587 │  *   DOSSIER:    running inference about the seven brief fields
 588 │  *   PROBE:      one typed follow-up (choice / multi / blanks / scale)
 589 │  *   SYNTHESIZE: the finished dossier, ending the interview
 590 │  *
 591 │  * The probe instruction is written as "reach for this when prose was vague"
 592 │  * rather than "use these sometimes", because a model told to vary its format
 593 │  * will vary it decoratively — asking a multiple-choice question it already
 594 │  * knows the answer to. The point of a typed question is to pin down something
 595 │  * a paragraph left soft.
 596 │  */
 597 │ function interviewSystemPrompt(
 598 │   mode: "first-run" | "refine",
 599 │   currentBrief: ProjectBrief | null,
 600 │   startingMaterial: string | null = null,
 601 │ ): string {
 602 │   const trimmed = startingMaterial?.trim();
 603 │   return [
 604 │     "You are a kind, incisive editorial interviewer helping a writer build a project dossier.",
 605 │     "Ask one question at a time. Keep it short. You are building a writer's room: identify the piece, reader, goal, tone, constraints, success signal, and what kind of advisors/editors the writer wants around it.",
 606 │     'After every ordinary question, append `DOSSIER:` followed by JSON { "brief": { workingTitle, format, audience, goal, tone, constraints, successSignal }, "confidence": { field: "high" | "medium" | "low" } }. Only include fields you can reasonably infer.',
 607 │     "",
 608 │     "SOMETIMES A QUESTION IS BETTER ASKED AS A CONTROL THAN AS PROSE. When the writer's last answer was vague, hedged, or covered two possibilities at once, and a typed question would pin it down in one tap, append `PROBE:` followed by JSON for exactly one of:",
 609 │     '  { "kind": "choice", "prompt": "<question>", "options": ["<2-6 options>"], "relatesTo": "<brief field>" }',
 610 │     '  { "kind": "multi", "prompt": "<question>", "options": ["<2-6 options>"], "relatesTo": "<brief field>" }',
 611 │     '  { "kind": "blanks", "prompt": "<instruction>", "template": "<a sentence with ___ where the writer fills in>", "relatesTo": "<brief field>" }',
 612 │     '  { "kind": "scale", "prompt": "<question>", "min": 1, "max": 5, "minLabel": "<what 1 means>", "maxLabel": "<what 5 means>", "relatesTo": "<brief field>" }',
 613 │     "Rules for probes: at most one per turn, and only when it genuinely narrows something. Never ask a probe whose answer you already have. Options must be concrete and mutually distinct — not 'clear / unclear'. `relatesTo` must be one of workingTitle, format, audience, goal, tone, constraints, successSignal. Still write your question text as normal prose above the tag; the probe is how they answer it, not a replacement for asking.",
 614 │     "",
 615 │     "When the dossier is complete enough for review, respond only with `SYNTHESIZE:` followed by the same JSON shape as DOSSIER. Put requested advisors/editors into constraints or goal until the product has a dedicated advisor schema.",
 616 │     mode === "refine" && currentBrief
 617 │       ? `Existing dossier: ${JSON.stringify(currentBrief.answers)} — refine it, don't restart.`
 618 │       : "",
 619 │     trimmed
 620 │       ? `The writer has already drafted the following manuscript. Read it before asking — orient the dossier around what is already on the page rather than starting from a blank brief.\n\n--- BEGIN MANUSCRIPT ---\n${trimmed}\n--- END MANUSCRIPT ---`
 621 │       : "",
 622 │   ]
 623 │     .filter(Boolean)
 624 │     .join("\n");
 625 │ }
