 627 │ function normalizeInterviewDossierDraft(value: unknown) {
 628 │   if (!value || typeof value !== "object") return null;
 629 │   const obj = value as Record<string, unknown>;
 630 │   const briefSource =
 631 │     obj.brief && typeof obj.brief === "object"
 632 │       ? (obj.brief as Record<string, unknown>)
 633 │       : obj;
 634 │   const confidenceSource =
 635 │     obj.confidence && typeof obj.confidence === "object"
 636 │       ? (obj.confidence as Record<string, unknown>)
 637 │       : {};
 638 │ 
 639 │   const brief: Partial<ProjectInterviewAnswers> = {};
 640 │   const confidence: Partial<
 641 │     Record<keyof ProjectInterviewAnswers, InterviewConfidence>
 642 │   > = {};
 643 │   for (const field of INTERVIEW_FIELDS) {
 644 │     const raw = briefSource[field];
 645 │     if (typeof raw === "string" && raw.trim()) {
 646 │       brief[field] = raw.trim();
 647 │     }
 648 │     const c = confidenceSource[field];
 649 │     if (c === "high" || c === "medium" || c === "low") {
 650 │       confidence[field] = c;
 651 │     }
 652 │   }
 653 │   return Object.keys(brief).length > 0 ? { brief, confidence } : null;
 654 │ }
