 656 │ function parseInterviewTurnResult(
 657 │   text: string,
 658 │   provider: string,
 659 │   model: string,
 660 │   messages: InterviewMessage[],
 661 │   traceId?: string,
 662 │ ): InterviewTurnResult {
 663 │   const visibleText = stripReasoningTags(text);
 664 │   if (!visibleText.trim()) {
 665 │     throw applicationError("malformed_response");
 666 │   }
 667 │   const lastUser = [...messages].reverse().find((m) => m.author === "writer");
 668 │   const synthSegment = extractTaggedJson(visibleText, "SYNTHESIZE");
 669 │   if (synthSegment) {
 670 │     const draft = normalizeInterviewDossierDraft(synthSegment.value);
 671 │     if (draft) {
 672 │       return {
 673 │         kind: "synthesis",
 674 │         brief: draft.brief as ProjectInterviewAnswers,
 675 │         confidence: draft.confidence,
 676 │         provider,
 677 │         model,
 678 │         traceId,
 679 │       };
 680 │     }
 681 │     throw applicationError("malformed_response");
 682 │   }
 683 │ 
 684 │   const legacySynthMatch = visibleText.match(
 685 │     /SYNTHESIZE:\s*(\{[\s\S]*?\})\s*(\{[\s\S]*?\})?/,
 686 │   );
 687 │   if (legacySynthMatch) {
 688 │     try {
 689 │       return {
 690 │         kind: "synthesis",
 691 │         brief: JSON.parse(legacySynthMatch[1]) as ProjectInterviewAnswers,
 692 │         confidence: legacySynthMatch[2]
 693 │           ? (JSON.parse(legacySynthMatch[2]) as Partial<
 694 │               Record<keyof ProjectInterviewAnswers, InterviewConfidence>
 695 │             >)
 696 │           : {},
 697 │         provider,
 698 │         model,
 699 │       };
 700 │     } catch {
 701 │       throw applicationError("malformed_response");
 702 │     }
 703 │   }
 704 │ 
 705 │   const dossierSegment = extractTaggedJson(visibleText, "DOSSIER");
 706 │   if (!dossierSegment && /\b(?:DOSSIER|SYNTHESIZE)\s*:/i.test(visibleText)) {
 707 │     throw applicationError("malformed_response");
 708 │   }
 709 │   const draft = dossierSegment
 710 │     ? normalizeInterviewDossierDraft(dossierSegment.value)
 711 │     : null;
 712 │ 
 713 │   // A probe is an optional garnish on a question, so a malformed one is
 714 │   // dropped rather than failing the turn — the writer still gets asked, just
 715 │   // in prose. This is why it does not join the strict tag check above.
 716 │   const probeSegment = extractTaggedJson(visibleText, "PROBE");
 717 │   const probe = probeSegment ? normalizeProbe(probeSegment.value) : null;
 718 │ 
 719 │   let body = visibleText;
 720 │   if (dossierSegment) body = stripTaggedJson(body, dossierSegment);
 721 │   if (probeSegment) {
 722 │     const reSegment = extractTaggedJson(body, "PROBE");
 723 │     if (reSegment) body = stripTaggedJson(body, reSegment);
 724 │   }
 725 │   const reply =
 726 │     body.trim() ||
 727 │     (lastUser ? "Tell me more." : "What is the working title of this piece?");
 728 │ 
 729 │   return {
 730 │     kind: "question",
 731 │     text: reply,
 732 │     draft: draft ?? undefined,
 733 │     probe: probe ?? undefined,
 734 │     provider,
 735 │     model,
 736 │     traceId,
 737 │   };
 738 │ }
