 740 │ export const runInterviewTurn = action({
 741 │   args: {
 742 │     messages: v.array(
 743 │       v.object({
 744 │         author: v.union(v.literal("writer"), v.literal("interviewer")),
 745 │         text: v.string(),
 746 │       }),
 747 │     ),
 748 │     mode: v.union(v.literal("first-run"), v.literal("refine")),
 749 │     currentBrief: briefValidator,
 750 │     streamId: v.optional(v.string()),
 751 │     /**
 752 │      * Manuscript text the writer has already drafted, surfaced by the
 753 │      * dossier refinery's "Start over" flow. When present, the system
 754 │      * prompt reads it as the starting context for the conversation so the
 755 │      * AI asks questions that fit the work-in-progress instead of
 756 │      * rediscovering it from scratch.
 757 │      */
 758 │     startingMaterial: v.optional(v.string()),
 759 │   },
 760 │   handler: async (ctx, args): Promise<InterviewTurnResult> => {
 761 │     const identity = await ctx.auth.getUserIdentity();
 762 │     if (!identity) {
 763 │       throw applicationError("authentication_required");
 764 │     }
 765 │     const provider = await pickProvider(ctx, "interview-turn", "balanced");
 766 │     if (!provider) {
 767 │       throw applicationError("provider_unavailable", {
 768 │         recovery: "open_settings",
 769 │       });
 770 │     }
 771 │ 
 772 │     const transcript = (args.messages as InterviewMessage[])
 773 │       .map((m) => `${m.author === "writer" ? "Writer" : "You"}: ${m.text}`)
 774 │       .join("\n");
 775 │     const temperature = provider.label === "openai" ? 0.6 : 0.4;
 776 │     const maxTokens = 420;
 777 │     const traceId = createAiTraceId("interview-turn");
 778 │     const start = Date.now();
 779 │     const input = JSON.stringify({
 780 │       mode: args.mode,
 781 │       transcript,
 782 │       startingMaterial: args.startingMaterial,
 783 │     });
 784 │     try {
 785 │       const generation = {
 786 │         model: provider.model,
 787 │         system: interviewSystemPrompt(
 788 │           args.mode,
 789 │           (args.currentBrief ?? null) as ProjectBrief | null,
 790 │           args.startingMaterial ?? null,
 791 │         ),
 792 │         prompt: transcript,
 793 │         temperature,
 794 │         maxOutputTokens: maxTokens,
 795 │         experimental_telemetry: {
 796 │           isEnabled: tracingEnabled,
 797 │           functionId: "interview-turn",
 798 │           metadata: {
 799 │             feature: "interview-turn",
 800 │             provider: provider.label,
 801 │             model: provider.modelId,
 802 │             mode: args.mode,
 803 │           },
 804 │         },
 805 │       };
 806 │       let text: string;
 807 │       let usage;
 808 │       if (args.streamId) {
 809 │         let rawText = "";
 810 │         let nativeReasoning = "";
 811 │         const streamed = streamText(generation);
 812 │         for await (const part of streamed.fullStream) {
 813 │           if (part.type === "text-delta") rawText += part.text;
 814 │           if (part.type === "reasoning-delta") nativeReasoning += part.text;
 815 │           if (
 816 │             part.type === "text-delta" ||
 817 │             part.type === "reasoning-delta" ||
 818 │             part.type === "reasoning-end"
 819 │           ) {
 820 │             const snapshot = createInterviewStreamSnapshot(
 821 │               rawText,
 822 │               nativeReasoning,
 823 │             );
 824 │             await ctx.runMutation(writeInterviewStreamReference, {
 825 │               userId: identity.subject || identity.tokenIdentifier,
 826 │               streamId: args.streamId,
 827 │               ...snapshot,
 828 │               status: "running",
 829 │             });
 830 │           }
 831 │         }
 832 │         text = await streamed.text;
 833 │         usage = normalizeAiUsage(await streamed.totalUsage);
 834 │         const finalSnapshot = createInterviewStreamSnapshot(
 835 │           text,
 836 │           nativeReasoning,
 837 │         );
 838 │         await ctx.runMutation(writeInterviewStreamReference, {
 839 │           userId: identity.subject || identity.tokenIdentifier,
 840 │           streamId: args.streamId,
 841 │           ...finalSnapshot,
 842 │           status: "complete",
 843 │         });
 844 │       } else {
 845 │         const result = await generateText(generation);
 846 │         text = result.text;
 847 │         usage = normalizeAiUsage(result.totalUsage);
 848 │       }
 849 │       await captureServerAiGeneration({
 850 │         feature: "interview-turn",
 851 │         provider: provider.label,
 852 │         model: provider.modelId,
 853 │         input,
 854 │         output: text,
 855 │         latencyMs: Date.now() - start,
 856 │         temperature,
 857 │         maxTokens,
 858 │         spanName: "interview-turn",
 859 │         usage,
 860 │         observability: {
 861 │           distinctId: identity.tokenIdentifier,
 862 │           traceId,
 863 │         },
 864 │         evalSignals: {
 865 │           twyne_interview_mode: args.mode,
 866 │           twyne_any_protocol_markers: [
 867 │             "DOSSIER:",
 868 │             "PROBE:",
 869 │             "SYNTHESIZE:",
 870 │           ],
 871 │         },
 872 │       });
 873 │       await flushArize();
 874 │       return parseInterviewTurnResult(
 875 │         text,
 876 │         provider.label,
 877 │         provider.modelId,
 878 │         args.messages as InterviewMessage[],
 879 │         traceId,
 880 │       );
 881 │     } catch (error) {
 882 │       await captureServerAiGeneration({
 883 │         feature: "interview-turn",
 884 │         provider: provider.label,
 885 │         model: provider.modelId,
 886 │         input,
 887 │         latencyMs: Date.now() - start,
 888 │         temperature,
 889 │         maxTokens,
 890 │         spanName: "interview-turn",
 891 │         observability: {
 892 │           distinctId: identity.tokenIdentifier,
 893 │           traceId,
 894 │         },
 895 │         error,
 896 │       });
 897 │       if (args.streamId) {
 898 │         await ctx
 899 │           .runMutation(writeInterviewStreamReference, {
 900 │             userId: identity.subject || identity.tokenIdentifier,
 901 │             streamId: args.streamId,
 902 │             text: "",
 903 │             reasoning: "",
 904 │             phase: "answer",
 905 │             status: "error",
 906 │           })
 907 │           .catch(() => undefined);
 908 │       }
 909 │       if (error instanceof Error && error.name === "ConvexError") {
 910 │         throw error;
 911 │       }
 912 │       throw reportedApplicationError(
 913 │         "agents.interview-turn",
 914 │         "provider_unavailable",
 915 │         error,
 916 │         { recovery: "retry" },
 917 │         {
 918 │           provider: provider.label,
 919 │           model: provider.modelId,
