1010 │ /** Parse the strict-JSON rewrite contract, tolerating code fences / prose. */
1011 │ function parseRewriteOutput(
1012 │   text: string,
1013 │ ): { replacement: string; rationale: string } | null {
1014 │   const stripped = stripReasoningTags(text)
1015 │     .trim()
1016 │     .replace(/^```(?:json)?/i, "")
1017 │     .replace(/```$/, "")
1018 │     .trim();
1019 │   const tryParse = (s: string) => {
1020 │     try {
1021 │       const o = JSON.parse(s);
1022 │       if (o && typeof o.replacement === "string" && o.replacement.trim()) {
1023 │         return {
1024 │           replacement: o.replacement.trim(),
1025 │           rationale: typeof o.rationale === "string" ? o.rationale.trim() : "",
1026 │         };
1027 │       }
1028 │     } catch {
1029 │       /* fall through */
1030 │     }
1031 │     return null;
1032 │   };
1033 │   return (
1034 │     tryParse(stripped) ?? tryParse(stripped.match(/\{[\s\S]*\}/)?.[0] ?? "")
1035 │   );
1036 │ }
