1721 │ function localEvidence(
1722 │   brief: ProjectBrief | null,
1723 │   draftText: string,
1724 │ ): { score: number; rationale: string; provider: "local" } {
1725 │   const features = scoreStaticFeatures(draftText).features;
1726 │   const density = features.citationDensity;
1727 │   let score: number;
1728 │   if (features.citationCount === 0) {
1729 │     score = clampScore(features.paragraphCount > 0 ? 3 : 1);
1730 │   } else if (density >= 1.5 && density <= 6) {
1731 │     score = 7;
1732 │   } else if (density < 1.5) {
1733 │     score = 5;
1734 │   } else {
1735 │     score = 4;
1736 │   }
1737 │   const audience = brief?.answers.audience || "the intended reader";
1738 │   const rationale = `${features.citationCount} citation-like reference${
1739 │     features.citationCount === 1 ? "" : "s"
1740 │   } (${density.toFixed(1)} per 1,000 words). This counts shape, not substance — judge locally only; production runs route through the LLM judge to catch padded or fake grounding. For ${audience}, evidence has to earn its claim.`;
1741 │   return { score, rationale, provider: "local" };
1742 │ }
1743 │ 
1744 │ function localIntegrity(draftText: string): {
1745 │   score: number;
1746 │   rationale: string;
1747 │   provider: "local";
1748 │ } {
1749 │   const features = scoreStaticFeatures(draftText).features;
1750 │   const deduction =
1751 │     features.unsupportedUniversalClaimCount * 0.6 +
1752 │     features.duplicateParagraphRatio * 60;
1753 │   const score = clampScore(
1754 │     deduction > 0 ? Math.max(1, 10 - Math.round(deduction)) : 7,
1755 │   );
1756 │   const rationale = `${features.unsupportedUniversalClaimCount} unsupported universal claim${
1757 │     features.unsupportedUniversalClaimCount === 1 ? "" : "s"
1758 │   }, ${(features.fillerWordRatio * 100).toFixed(1)}% filler, ${(
1759 │     features.vagueWordRatio * 100
1760 │   ).toFixed(1)}% vague wording, ${(
1761 │     features.duplicateParagraphRatio * 100
1762 │   ).toFixed(
1763 │     0,
1764 │   )}% duplicated paragraphs. Regex misses sophisticated bullshit and false-positives on legitimate emphatic prose — judge locally only; production runs route through the LLM judge.`;
1765 │   return { score, rationale, provider: "local" };
1766 │ }
