1769 │   const f = scoreStaticFeatures(draftText).features;
1770 │   return `Citation count: ${f.citationCount}, citation density: ${f.citationDensity.toFixed(
1771 │     1,
1772 │   )} per 1,000 words, paragraphs: ${f.paragraphCount}.`;
1773 │ }
