1777 │   return `Unsupported universal claims (regex): ${f.unsupportedUniversalClaimCount}; filler ratio: ${(
1778 │     f.fillerWordRatio * 100
1779 │   ).toFixed(1)}%; vague-wording ratio: ${(f.vagueWordRatio * 100).toFixed(
1780 │     1,
1781 │   )}%; duplicated paragraphs: ${(f.duplicateParagraphRatio * 100).toFixed(0)}%.`;
1782 │ }
