2205 │ /** Parse the criteria-suggestion contract, tolerating fences and stray prose. */
2206 │ function parseSuggestedCriteria(
2207 │   text: string,
2208 │ ): Array<{ label: string; description: string }> {
2209 │   const cleaned = text
2210 │     .trim()
2211 │     .replace(/^```(?:json)?/i, "")
2212 │     .replace(/```$/, "")
2213 │     .trim();
2214 │   const candidates = [cleaned, cleaned.match(/\{[\s\S]*\}/)?.[0] ?? ""];
2215 │   for (const candidate of candidates) {
2216 │     if (!candidate) continue;
2217 │     try {
2218 │       const parsed = JSON.parse(candidate) as {
2219 │         criteria?: Array<{ label?: unknown; description?: unknown }>;
2220 │       };
2221 │       const list = Array.isArray(parsed.criteria) ? parsed.criteria : [];
2222 │       const out = list
2223 │         .map((c) => ({
2224 │           label: typeof c.label === "string" ? c.label.trim().slice(0, 120) : "",
2225 │           description:
2226 │             typeof c.description === "string"
2227 │               ? c.description.trim().slice(0, 400)
2228 │               : "",
2229 │         }))
2230 │         .filter((c) => c.label);
2231 │       if (out.length > 0) return out.slice(0, 5);
2232 │     } catch {
2233 │       /* try the next candidate */
2234 │     }
2235 │   }
