2281 │           const user =
2282 │             buildUserPrompt({
2283 │               persona,
2284 │               brief,
2285 │               draftText: args.draftText,
2286 │               instruction: "feedback",
2287 │             }) +
2288 │             `
2289 │ 
2290 │ JUDGE TASK: Give the draft an integer score from 1 to 10. 5 is "doing the work but with clear issues." 7 is "in good shape." 9 is "publishable as-is." Be honest.
2291 │ 
2292 │ Do not reward confident-sounding bullshit. Penalize generic filler, repeated paragraphs, unsupported universal claims, vibes without evidence, fake specificity, and any passage that sounds polished while dodging the stated audience/goal.
2293 │ 
2294 │ Respond with JSON only: {"score": <int>, "rationale": "<one sentence in your voice>"}`;
2295 │           const start = Date.now();
2296 │           const temperature = 0.2;
2297 │           const maxTokens = 200;
2298 │           const { text } = await generateText({
2299 │             model: provider.model,
2300 │             system,
2301 │             prompt: user,
2302 │             temperature,
2303 │             maxOutputTokens: maxTokens,
2304 │             experimental_telemetry: {
2305 │               isEnabled: tracingEnabled,
2306 │               functionId: "rubric_judge_room",
