2309 │                 persona: persona.id,
2310 │                 provider: provider.label,
2311 │                 model: provider.modelId,
2312 │               },
2313 │             },
2314 │           });
2315 │           const visibleText = stripReasoningTags(text);
2316 │           await captureServerAiGeneration({
2317 │             feature: "rubric-judge",
2318 │             provider: provider.label,
2319 │             model: provider.modelId,
2320 │             req: {
2321 │               persona,
