2355 │ async function runHostedAgent(
2356 │   ctx: ActionCtx,
2357 │   req: AgentRequest,
2358 │   observability?: ServerAiObservabilityContext,
2359 │ ): Promise<AgentResponse> {
2360 │   const feature =
2361 │     req.userMessage || req.priorMessages?.length
2362 │       ? "persona-reply"
2363 │       : "persona-feedback";
2364 │   const provider = await pickProvider(ctx, feature, "balanced");
2365 │   if (!provider) {
2366 │     throw applicationError("provider_unavailable", {
2367 │       recovery: "open_settings",
2368 │     });
2369 │   }
2370 │   try {
2371 │     const identity = await ctx.auth.getUserIdentity();
2372 │     return await runLlm(provider, req, feature, 380, {
2373 │       ...observability,
2374 │       distinctId: identity?.tokenIdentifier,
2375 │     });
2376 │   } catch (err) {
2377 │     throw reportedApplicationError(
2378 │       `agents.${feature}`,
2379 │       "provider_unavailable",
2380 │       err,
2381 │       { recovery: "retry" },
2382 │       {
2383 │         provider: provider.label,
2384 │         model: provider.modelId,
2385 │       },
2386 │     );
2387 │   }
2388 │ }
2389 │ 
2390 │ function localJudge(
2391 │   persona: AgentPersona,
2392 │   brief: ProjectBrief | null,
2393 │   draftText: string,
2394 │ ): { score: number; rationale: string; provider: "local" } {
2395 │   const wc = draftText.split(/\s+/).filter(Boolean).length;
2396 │   const hasBrief = !!brief;
2397 │   const hasBody = wc > 80;
2398 │   let base = 3;
2399 │   if (hasBrief) base += 1;
2400 │   if (hasBody) base += 1;
2401 │   if (wc > 350) base += 1;
2402 │   if (wc > 800) base += 1;
2403 │ 
2404 │   // Persona-shaped adjustments — each persona reads different things.
2405 │   const id = persona.id;
2406 │   let bias = 0;
2407 │   let rationale =
2408 │     "The draft is partial; the work to come is the interesting part.";
2409 │   if (id === "devil") {
2410 │     bias = wc < 200 ? -1 : 0;
2411 │     rationale =
2412 │       wc < 200
2413 │         ? "The argument is still under construction; the load-bearing claim is not yet visible."
2414 │         : "The argument moves, but the strongest counter-objection is still unstated.";
2415 │   } else if (id === "angel") {
2416 │     bias = hasBody ? 1 : 0;
2417 │     rationale = hasBody
2418 │       ? "There is at least one paragraph doing real work; protect it."
2419 │       : "The opening gestures are honest; trust them, then add weight.";
2420 │   } else if (id === "scholar") {
2421 │     bias = -1; // be strict on evidence
2422 │     rationale = "Claims outrun evidence; the bibliography is thin.";
2423 │   } else if (id === "editor") {
2424 │     bias = wc > 200 ? 0 : -1;
2425 │     rationale =
2426 │       wc > 200
2427 │         ? "Sentences are present, but rhythm and concision need a pass."
2428 │         : "The draft is too short to evaluate the cut; write more first.";
2429 │   } else if (id === "reader") {
2430 │     bias = hasBrief ? 0 : -1;
2431 │     rationale = hasBrief
2432 │       ? "As the named audience, I would keep reading past the open."
2433 │       : "Without a clear audience, the opening is interesting but slippery.";
2434 │   }
2435 │   return { score: clampScore(base + bias), rationale, provider: "local" };
2436 │ }
2437 │ 
2438 │ /* ── Internal: allow other Convex files to call the runner. ─────── */
2439 │ 
2440 │ export { runLlm, pickProvider };
